const body = {};

// Include 'stations' key if 'stations' is provided
if (typeof inputs.stations !== 'undefined') {
  body.stations = inputs.stations;
} else {
  body.stations =  (function(apiStations, configStations) {
    // Normalize values to lowercase and create sets for uniqueness
    const apiSet = new Set(apiStations?.map(station => station.toLowerCase()));
    const configSet = new Set(configStations?.map(station => station.toLowerCase()));

    // Merge the two sets
    const mergedSet = new Set([...apiSet, ...configSet]);

    // Convert back to array with original case from the API data as a priority, and if not, from config
    const reconciledList = Array.from(mergedSet).map(station => {
        // Find the original case-sensitive station name from the API or config array
        const apiMatch = apiStations?.find(s => s.toLowerCase() === station);
        return apiMatch ? apiMatch : configStations?.find(s => s.toLowerCase() === station);
    });

    return reconciledList;
})(queries.stationListApi.data.swiggy_supported_junctions, variables.STATION_LIST.value)
 }

// Global variables to include if provided
const globalKeys = [
  'cuisines',
  'minimumOrderValue',
  'bookingCutoffTime',
  'openingTime',
  'closingTime',
  'advanceBookingLimit',
  'hasPromotion',
  'minimumHaltTimeMinutes',
];

const globalDefaultConfig = {
  "cuisines": ["North Indian","South Indian"],
  "minimumOrderValue": 100, 
  "bookingCutoffTime": 60,  
  "openingTime": "06:00", 
  "closingTime": "23:00",
  "advanceBookingLimit": 24,
  "hasPromotion": false,
  "minimumHaltTimeMinutes": 2
}

globalKeys.forEach((key) => {
  if (typeof inputs[key] !== 'undefined') {
    body[key] = inputs[key];
  } 
});

// Merge station-wise overrides directly into the body
if (typeof inputs.stationWiseOverRides !== 'undefined') {
  body.stationData = [inputs.stationWiseOverRides];
   // also send default values for global keys
  Object.keys(globalDefaultConfig).forEach(function(key) {
    body[key] = globalDefaultConfig[key];
});
}

return body;
